import{_ as s,o as i,c as a,ai as t}from"./chunks/framework.C33Uq6m-.js";const h=JSON.parse('{"title":"Complétion au Milieu (FIM)","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/fim.md","filePath":"fr/guide/fim.md"}'),l={name:"fr/guide/fim.md"};function n(o,e,r,u,p,d){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="completion-au-milieu-fim" tabindex="-1">Complétion au Milieu (FIM) <a class="header-anchor" href="#completion-au-milieu-fim" aria-label="Permalink to &quot;Complétion au Milieu (FIM)&quot;">​</a></h1><p>La <strong>page FIM</strong> est un petit terrain de jeu dédié à la <strong>complétion de code</strong>. Vous fournissez un <strong>préfixe</strong> (le code avant le curseur) et un <strong>suffixe</strong> (le code après le curseur), et le modèle remplit le trou entre les deux.</p><p><strong>Élément de barre latérale :</strong> Complétion de code (sous Atelier d&#39;Outils) <strong>Route :</strong> <code>/fim</code><strong>Ajouté dans :</strong> v0.4.7 (mai 2026)</p><h2 id="qu-est-ce-que-la-completion-au-milieu" tabindex="-1">Qu&#39;est-ce que la complétion au milieu ? <a class="header-anchor" href="#qu-est-ce-que-la-completion-au-milieu" aria-label="Permalink to &quot;Qu&#39;est-ce que la complétion au milieu ?&quot;">​</a></h2><p>La plupart des APIs de chat ne supportent que la génération de gauche à droite : vous donnez un prompt, le modèle continue à partir de là. <strong>FIM</strong> est différent — le modèle voit aussi ce qui vient <em>après</em> le trou, et écrit du contenu qui s&#39;insère naturellement entre les deux ancres.</p><p>C&#39;est ce qui anime des outils comme la suggestion en milieu de ligne de GitHub Copilot et la « complétion tab » de Cursor. Plusieurs modèles servis par Ollama le supportent nativement :</p><ul><li><strong>Qwen2.5-Coder</strong> (toutes tailles)</li><li><strong>CodeLlama</strong> (variantes <code>-code</code>)</li><li><strong>Codestral</strong></li><li><strong>DeepSeek-Coder</strong></li><li><strong>StarCoder</strong></li></ul><p>Ollama expose le FIM via un champ <code>suffix</code> sur l&#39;endpoint <code>/api/generate</code>. LLMxRay le rend disponible dans la page FIM.</p><h2 id="utilisation" tabindex="-1">Utilisation <a class="header-anchor" href="#utilisation" aria-label="Permalink to &quot;Utilisation&quot;">​</a></h2><ol><li>Choisissez un modèle dans la liste déroulante — les modèles de code sont listés en premier sous « Modèles de code (compatibles FIM) ».</li><li>Tapez votre <strong>préfixe</strong> (le code qui vient avant le curseur) dans la zone de texte de gauche.</li><li>Tapez votre <strong>suffixe</strong> (le code qui vient après le curseur) dans la zone de droite.</li><li>Cliquez sur <strong>Générer</strong>.</li></ol><p>Le modèle diffuse le milieu manquant en temps réel. Après la génération, un <strong>aperçu assemblé</strong> apparaît — le préfixe, le milieu généré (surligné en couleur d&#39;accent), et le suffixe rendus comme un seul bloc continu, comme ils apparaîtraient dans votre éditeur.</p><h2 id="metriques" tabindex="-1">Métriques <a class="header-anchor" href="#metriques" aria-label="Permalink to &quot;Métriques&quot;">​</a></h2><p>Quand la génération se termine, quatre cartes de métriques apparaissent sous la sortie :</p><ul><li><strong>Durée totale</strong> — temps mural entre la requête et le dernier token</li><li><strong>Chargement modèle</strong> — temps qu&#39;Ollama a passé à charger le modèle en mémoire (0 ms pour les démarrages à chaud)</li><li><strong>Tokens générés</strong> — nombre de tokens produits par le modèle</li><li><strong>Vitesse</strong> — tokens par seconde</li></ul><h2 id="si-le-modele-ne-supporte-pas-fim" tabindex="-1">Si le modèle ne supporte pas FIM <a class="header-anchor" href="#si-le-modele-ne-supporte-pas-fim" aria-label="Permalink to &quot;Si le modèle ne supporte pas FIM&quot;">​</a></h2><p>Si vous choisissez un modèle qui n&#39;est pas de code, la page vous avertit en amont. Si vous essayez quand même, Ollama renvoie une erreur claire : <code>qwen2.5:3b does not support insert</code> (ou similaire, avec le nom du modèle à la place). La page affiche ce message dans la zone de sortie sans planter.</p><h2 id="sous-le-capot" tabindex="-1">Sous le capot <a class="header-anchor" href="#sous-le-capot" aria-label="Permalink to &quot;Sous le capot&quot;">​</a></h2><p>La page appelle <code>/api/generate</code> avec le nouveau champ <code>suffix</code> qu&#39;Ollama expose :</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;qwen2.5-coder:7b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;prompt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;def fibonacci(n):</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    if n &lt;= 1:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        return n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;suffix&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">print(fibonacci(10))&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>La réponse NDJSON streamée est analysée de la même façon qu&#39;un chat normal — un objet JSON par ligne, accumulant les deltas <code>response</code> jusqu&#39;à <code>done: true</code>.</p><h2 id="voir-aussi" tabindex="-1">Voir aussi <a class="header-anchor" href="#voir-aussi" aria-label="Permalink to &quot;Voir aussi&quot;">​</a></h2><ul><li><a href="./chat-diagnostics.html">Diagnostics de Chat</a> pour le chat général</li><li><a href="./tool-workshop.html">Atelier d&#39;Outils</a> pour construire des outils agentiques</li></ul>`,22)])])}const m=s(l,[["render",n]]);export{h as __pageData,m as default};
